QS = [('Hakeem Force Academy', 'What was the relation of Hazrat Zainab (RA) with the Holy Prophet Muhammad (PBUH)?', ['Wife', 'Eldest daughter', 'Aunt', 'Foster sister'], 1, 'Hazrat Zainab (RA) was the eldest daughter of the Holy Prophet (PBUH) and Hazrat Khadijah (RA).', 'She was married to Abul As bin Rabi.', [3949]),
 ('Hakeem Force Academy', 'What was the relation of Hazrat Ruqayyah (RA) with the Holy Prophet Muhammad (PBUH)?', ['Daughter', 'Wife', 'Paternal aunt', 'Mother'], 0, 'Hazrat Ruqayyah (RA) was a daughter of the Holy Prophet (PBUH) and Hazrat Khadijah (RA).', 'She was married to Hazrat Uthman (RA), who later also married her sister Umm Kulthum (RA).', [3951]),
 ('Hakeem Force Academy', 'In which year was the film Jinnah, starring Christopher Lee as the Quaid-e-Azam, released?', ['1996', '1998', '2001', '2005'], 1, 'The British-Pakistani biographical film Jinnah, directed by Jamil Dehlavi, was released in 1998.', 'Christopher Lee played Muhammad Ali Jinnah and Shashi Kapoor appeared as the narrator.', [114, 765, 418]),
 ('Hakeem Force Academy', 'Which is the largest religion in the world by number of followers?', ['Islam', 'Hinduism', 'Christianity', 'Buddhism'], 2, 'Christianity has about 2.4 billion followers, more than any other religion.', 'Islam is the second largest religion and is the fastest growing.', [972]),
 ('Hakeem Force Academy', 'Which Muslim League leader responded to the Nehru Report (1928) with his famous Fourteen Points in 1929?', ['Allama Iqbal', 'Quaid-e-Azam Muhammad Ali Jinnah', 'Liaquat Ali Khan', 'Sir Aga Khan'], 1, 'The Nehru Report rejected separate electorates and Muslim demands, so Jinnah presented his Fourteen Points in March 1929 as the Muslim reply.', 'Jinnah had earlier put forward his Delhi Muslim Proposals in 1927.', [3894, 3937, 5010]),
 ('Hakeem Force Academy', 'What do the five interlocking rings of the Olympic flag represent?', ['Five sports', 'Five continents (Africa, America, Asia, Europe, Oceania) united by Olympism', 'Five founding nations', 'Five Olympic ideals'], 1, 'The five rings stand for the five inhabited continents joined together by the Olympic movement.', 'The rings are blue, yellow, black, green and red on a white background, and every national flag contains at least one of these colours.', [2924, 840, 2887, 841]),
 ('Hakeem Force Academy', 'What is the age required to be qualified as a member (and so to become Speaker) of the National Assembly of Pakistan?', ['21 years', '25 years', '30 years', '35 years'], 1, 'Under Article 62 and 51 of the 1973 Constitution, a person must be at least 25 years old to be a member of the National Assembly, and the Speaker is elected from its members.', 'A person must be at least 35 years old to be elected President.', [3122]),
 ('Hakeem Force Academy', 'Against whom was the Reshmi Rumal (Silk Letters) Movement directed?', ['The Sikhs', 'The Hindu Congress', 'The British rulers of India', 'The Marathas'], 2, 'The movement, led by Maulana Mahmud Hasan, aimed to end British rule in India with help from Afghanistan, Turkey and Germany.', 'It was discovered in 1916 when the silk letters were intercepted.', [1446]),
 ('Hakeem Force Academy', 'What was the Lahore Resolution of 23 March 1940?', ['A demand for separate independent states for the Muslims of India', 'A demand for a united India', 'An agreement with the Congress', 'A plan to boycott the elections of 1946'], 0, 'At the Lahore session of the All-India Muslim League, the resolution demanded that Muslim-majority areas in the north-west and east be grouped into independent states.', 'It was moved by A. K. Fazlul Haq and later called the Pakistan Resolution.', [3451, 3916]),
 ('Hakeem Force Academy', 'Which is generally regarded as the last complete surah of the Quran to be revealed?', ['Surah Al-Fatiha', 'Surah An-Nasr', 'Surah Al-Ikhlas', 'Surah Al-Alaq'], 1, 'Surah An-Nasr is regarded as the last complete surah revealed, shortly before the death of the Prophet (PBUH).', 'Scholars differ, and some name verses of Surah Al-Baqarah or Surah Al-Maidah as the last verses revealed.', [547]),
 ('Hakeem Force Academy', 'What is the national river of Pakistan?', ['Jhelum', 'Chenab', 'Indus', 'Ravi'], 2, 'The Indus is the longest and largest river of Pakistan and is regarded as its national river.', 'It rises near Lake Mansarovar in Tibet and falls into the Arabian Sea near Karachi.', [497]),
 ('Hakeem Force Academy', 'Complete the proverb: A rolling stone gathers no ________.', ['moss', 'dust', 'mass', 'speed'], 0, 'The proverb means that a person who keeps moving from place to place or job to job does not build up wealth or roots.', 'The word moss in the proverb stands for success and a settled life.', [1615])]
